parameters.query:
=[
  {
    "$match": {
      "timestamp": {
        "$gte": "{{ new Date(new Date().setHours(0,0,0,0) - 86400000).toISOString() }}",
        "$lt":  "{{ new Date(new Date().setHours(0,0,0,0)).toISOString() }}"
      }
    }
  },
  {
    "$group": {
      "_id": { "ap_name": "$ap_name", "domain": "$domain", "risk_level": "$risk_level" },
      "count": { "$sum": 1 },
      "unique_clients": { "$addToSet": "$client_ip" }
    }
  },
  {
    "$project": {
      "ap_name":      "$_id.ap_name",
      "domain":       "$_id.domain",
      "risk_level":   "$_id.risk_level",
      "count":        1,
      "client_count": { "$size": "$unique_clients" }
    }
  },
  { "$sort": { "count": -1 } },
  { "$limit": 200 }
]

parameters.jsCode:
const todayItems   = $('Ambil Data Harian').all().map(i => i.json);
const historyItems = $('Ambil Historis 7 Hari').all().map(i => i.json);

if (todayItems.length === 0) {
  return [{ json: { _skip: true, reason: 'Tidak ada data untuk periode ini' } }];
}

// Tanggal laporan (kemarin, WIB)
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const dateLabel = yesterday.toLocaleDateString('id-ID', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Jakarta'
});

// Kelompokkan per AP
const byAP = {};
for (const row of todayItems) {
  const ap = row.ap_name || 'Unknown AP';
  if (!byAP[ap]) byAP[ap] = [];
  byAP[ap].push(row);
}

const apSummaries = Object.entries(byAP).map(([ap, rows]) => {
  const totalQueries = rows.reduce((s, r) => s + (r.count || 0), 0);
  const uniqueClients = new Set(rows.map(r => r.client_count)).size;
  const top3 = rows.slice(0, 3).map(r => `${r.domain} (${r.count}x, ${r.risk_level})`).join(', ');
  const flagCount  = rows.filter(r => r.risk_level === 'flag').reduce((s, r)  => s + r.count, 0);
  const watchCount = rows.filter(r => r.risk_level === 'watch').reduce((s, r) => s + r.count, 0);
  return `\nAccess Point: ${ap}\n- Total query: ${totalQueries}\n- IP klien unik: ${uniqueClients}\n- Top 3 domain: ${top3}\n- Domain berisiko (flag): ${flagCount}\n- Domain perlu perhatian (watch): ${watchCount}`;
}).join('\n');

// Ringkasan historis untuk perbandingan tren
const histSummary = historyItems.length > 0
  ? `Data historis 7 hari terakhir tersedia (${historyItems.length} laporan). Gunakan untuk perbandingan tren persentase naik/turun jika relevan.\n` +
    JSON.stringify(historyItems.map(h => ({ date: h.date_label, raw_rows: h.raw_rows })))
  : 'Tidak ada data historis tersedia untuk perbandingan.';

const prompt = `Kamu adalah analis keamanan jaringan sekolah. Analisa data DNS traffic berikut dan buat laporan dalam Bahasa Indonesia.

Tanggal: ${dateLabel}

Data trafik per Access Point:
${apSummaries}

${histSummary}

Format laporan WAJIB:
📊 LAPORAN TRAFFIC DNS — ${dateLabel}
1. Ringkasan Umum (2-3 kalimat)
2. Temuan Per Access Point (bullet point per AP, sertakan jumlah IP unik dan top domain)
3. Perbandingan Tren vs 7 Hari Terakhir (sebutkan kenaikan/penurunan dalam persen jika data tersedia)
4. Domain Paling Aktif (top 5 keseluruhan)
5. Rekomendasi Tindakan (jika ada domain berisiko atau pola mencurigakan)

Jawab HANYA dengan laporan terformat, tanpa penjelasan tambahan.`;

return [{
  json: {
    _skip:      false,
    date_label: dateLabel,
    prompt,
    raw_rows:   todayItems.length,
    ap_count:   Object.keys(byAP).length,
    timestamp:  new Date().toISOString()
  }
}];

